import{_ as a,o,c as r,a2 as t}from"./chunks/framework.BZO4qERu.js";const m=JSON.parse('{"title":"了解 Memoh","description":"","frontmatter":{},"headers":[],"relativePath":"zh/about.md","filePath":"zh/about.md","lastUpdated":1790952322000}'),s={name:"zh/about.md"};function l(h,e,n,i,p,d){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="了解-memoh" tabindex="-1">了解 Memoh <a class="header-anchor" href="#了解-memoh" aria-label="Permalink to &quot;了解 Memoh&quot;">​</a></h1><p>Memoh v0.13 是开源的多智能体平台。它让你在一台机器上运行多个 AI Agent，并为每个 Agent 提供自己的 workspace、浏览器、网络、工具和长期记忆。</p><p>Agent 可以通过 Telegram、Discord、Slack、飞书、微信、钉钉等渠道对话，也可以直接在 Memoh 客户端里聊；也可以记住上下文、操作浏览器或桌面、调用 MCP 工具、安装技能和连接器、执行定时任务，并按 Bot 配置访问权限。</p><p>更想使用托管服务、而不是自己运维部署？<a href="https://app.memoh.net" target="_blank" rel="noreferrer">Memoh Cloud</a> 提供与开源版一致的托管服务。</p><h2 id="分发方式" tabindex="-1">分发方式 <a class="header-anchor" href="#分发方式" aria-label="Permalink to &quot;分发方式&quot;">​</a></h2><h3 id="desktop" tabindex="-1">Desktop <a class="header-anchor" href="#desktop" aria-label="Permalink to &quot;Desktop&quot;">​</a></h3><p>Desktop 是 Memoh Cloud 或自托管服务端的原生客户端。它把同一套客户端界面包进带系统托盘与快捷键的原生窗口，并可把所在电脑注册为 Bot 可用的 Computer。它不会运行本地服务端。</p><h3 id="server-deploy" tabindex="-1">Server Deploy <a class="header-anchor" href="#server-deploy" aria-label="Permalink to &quot;Server Deploy&quot;">​</a></h3><p>Server Deploy 适合长期在线和多人共享。只要 Memoh 需要服务多个用户、在你的个人电脑离线时继续接入渠道，或作为自托管服务运行，就应该用这一形态。Docker Compose stack 包含后端、网页客户端、数据库、记忆服务和 workspace runtime。</p><h2 id="v0-13-重点" tabindex="-1">v0.13 重点 <a class="header-anchor" href="#v0-13-重点" aria-label="Permalink to &quot;v0.13 重点&quot;">​</a></h2><h3 id="agent-workspaces" tabindex="-1">Agent Workspaces <a class="header-anchor" href="#agent-workspaces" aria-label="Permalink to &quot;Agent Workspaces&quot;">​</a></h3><p>每个 Bot 可以使用隔离容器 workspace，拥有文件、命令、MCP 托管、网络访问、有头浏览器和图形桌面。本地与桌面部署也可以在明确受信任时使用 trusted local workspace。</p><h3 id="客户端" tabindex="-1">客户端 <a class="header-anchor" href="#客户端" aria-label="Permalink to &quot;客户端&quot;">​</a></h3><p>客户端覆盖了更多日常操作：Bot 设置、会话、模型服务商、渠道、workspace 文件、终端和桌面面板、应用市场、Hooks、定时任务、访问控制和用户偏好。v0.13 也包含英文、简体中文和日文界面支持。</p><h3 id="hooks、定时任务与自动化" tabindex="-1">Hooks、定时任务与自动化 <a class="header-anchor" href="#hooks、定时任务与自动化" aria-label="Permalink to &quot;Hooks、定时任务与自动化&quot;">​</a></h3><p>Hooks 可以围绕支持的事件运行小型自动化规则，Schedule 则让周期性工作不依赖正在进行的聊天。来自应用市场的技能与连接器无需写代码即可扩展 Bot 的能力。</p><h3 id="访问控制" tabindex="-1">访问控制 <a class="header-anchor" href="#访问控制" aria-label="Permalink to &quot;访问控制&quot;">​</a></h3><p>访问控制分成渠道侧聊天权限和 workspace 侧用户权限。Bot owner 可以允许或屏蔽渠道成员，给注册用户授予 workspace 角色，并在需要更精细匹配时继续使用高级 ACL 规则。</p><h2 id="从哪开始" tabindex="-1">从哪开始 <a class="header-anchor" href="#从哪开始" aria-label="Permalink to &quot;从哪开始&quot;">​</a></h2><ul><li><strong><a href="./guides/working-with-bots.html">Bot</a></strong> - 创建并配置 Bot。</li><li><strong><a href="./integrations/providers/llm.html">模型服务商与模型</a></strong> - 配置模型访问。</li><li><strong><a href="./integrations/channels/">渠道</a></strong> - 选择 Bot 出现的位置。</li><li><strong><a href="./guides/skills.html">技能</a></strong> 和 <strong><a href="./guides/supermarket.html">应用市场</a></strong> - 安装可复用能力。</li><li><strong><a href="./guides/schedule.html">定时任务</a></strong> 和 <strong><a href="./guides/access.html">访问控制</a></strong> - 运维周期性工作和权限。</li><li><strong><a href="https://memoh.ai/help" target="_blank" rel="noreferrer">帮助中心</a></strong> - 订阅、账单与账号类问题，以及联系团队的入口。</li></ul>',20)])])}const u=a(s,[["render",l]]);export{m as __pageData,u as default};
